#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "input/input.h"
#include "inventory/inventory.h"
#include "ui/display.h"

static void save(const Inventory *i){InventoryStatus s=inventory_storage_save(i,INVENTORY_DEFAULT_CSV_PATH);if(s!=INVENTORY_OK)printf("Warning: %s\n",inventory_status_message(s));}
static InputAction fields(Product *p){InputAction a=read_nonempty_string("Enter product name: ",p->name,sizeof(p->name));if(a==INPUT_OK)a=read_nonempty_string("Enter category: ",p->category,sizeof(p->category));if(a==INPUT_OK)a=read_money("Enter unit price: ",&p->price_cents);if(a==INPUT_OK)a=read_int_in_range("Enter quantity: ",0,999999999,&p->quantity);return a;}
static InputAction get_sku(const char *prompt,int *sku){return read_int_in_range(prompt,1,999999999,sku);}
static InputAction add(Inventory *i){Product p={0};char prompt[100];snprintf(prompt,sizeof(prompt),"\nEnter SKU (e.g. %d): ",inventory_next_sku(i));InputAction a=get_sku(prompt,&p.sku);if(a!=INPUT_OK)return a;if(inventory_find_by_sku(i,p.sku)){printf("%s\n\n",inventory_status_message(INVENTORY_ERR_DUPLICATE_SKU));return INPUT_OK;}a=fields(&p);if(a!=INPUT_OK)return a;InventoryStatus s=inventory_add(i,&p);if(s==INVENTORY_OK){save(i);printf("Product #%d added and saved.\n\n",p.sku);}else printf("%s\n\n",inventory_status_message(s));return INPUT_OK;}
static InputAction search(const Inventory *i){if(!i->count){puts("\nNo products to search.\n");return INPUT_OK;}char q[PRODUCT_NAME_MAX];InputAction a=read_nonempty_string("\nEnter SKU, name, or category: ",q,sizeof(q));if(a!=INPUT_OK)return a;int sku=0,has_sku=parse_int(q,&sku);size_t found=0;for(size_t x=0;x<i->count;++x)if((has_sku&&i->items[x].sku==sku)||product_matches(&i->items[x],q)){if(!found++){puts("");print_product_header();}print_product_row(&i->items[x]);}if(found)print_product_footer(found);else printf("No products matched \"%s\".\n\n",q);return INPUT_OK;}
static InputAction update(Inventory *i){int sku;InputAction a=get_sku("\nEnter SKU to update: ",&sku);if(a!=INPUT_OK)return a;const Product *old=inventory_find_by_sku(i,sku);if(!old){printf("%s\n\n",inventory_status_message(INVENTORY_ERR_NOT_FOUND));return INPUT_OK;}puts("\nCurrent record:");print_product_header();print_product_row(old);print_product_footer(1);Product p={0};p.sku=sku;a=fields(&p);if(a!=INPUT_OK)return a;InventoryStatus s=inventory_update(i,sku,&p);if(s==INVENTORY_OK){save(i);puts("Product updated and saved.\n");}else printf("%s\n\n",inventory_status_message(s));return INPUT_OK;}
static InputAction quantity_change(Inventory *i,int selling){int sku,qty;InputAction a=get_sku(selling?"\nEnter SKU to sell: ":"\nEnter SKU to restock: ",&sku);if(a!=INPUT_OK)return a;a=read_int_in_range("Enter quantity: ",1,999999999,&qty);if(a!=INPUT_OK)return a;InventoryStatus s=selling?inventory_sell(i,sku,qty):inventory_restock(i,sku,qty);if(s==INVENTORY_OK){save(i);puts("Inventory saved.\n");}else printf("%s\n\n",inventory_status_message(s));return INPUT_OK;}
static InputAction remove_product(Inventory *i){int sku;InputAction a=get_sku("\nEnter SKU to remove: ",&sku);if(a!=INPUT_OK)return a;InventoryStatus s=inventory_remove(i,sku);if(s==INVENTORY_OK){save(i);puts("Product removed and saved.\n");}else printf("%s\n\n",inventory_status_message(s));return INPUT_OK;}
int main(void){Inventory i;inventory_init(&i);(void)inventory_storage_load(&i,INVENTORY_DEFAULT_CSV_PATH);print_banner();for(;;){print_main_menu(i.count);int choice;InputAction a=read_int_in_range("Select option (1-8): ",1,8,&choice);if(a==INPUT_RESET){clear_screen();print_banner();continue;}if(a!=INPUT_OK||choice==8)break;switch(choice){case 1:a=add(&i);break;case 2:print_inventory(&i);break;case 3:a=search(&i);break;case 4:a=update(&i);break;case 5:a=quantity_change(&i,0);break;case 6:a=quantity_change(&i,1);break;default:a=remove_product(&i);}if(a==INPUT_RESET){clear_screen();print_banner();}else if(a!=INPUT_OK)break;}inventory_free(&i);puts("Goodbye!");return EXIT_SUCCESS;}
